			local swayX_extra = math.sin(t * 1.2) * 0.1
			local swayZ_extra = math.cos(t * 1.5) * 0.1

			local offset = Vector3.new(spinX + swayX_extra, swayY, spinZ + swayZ_extra)

			local partsToSync = {
				{
					Part = head,
					MeshId = headMesh.MeshId,
					Offset = offset
				}
			}

			for _, hat in hats do
