		if not tool then return end

		local remote = tool.SyncAPI.ServerEndpoint
		local function _(args)
			remote:InvokeServer(unpack(args))
		end

		function SetRotation(part, rotation)
			local args = {
				[1] = "SyncRotate",
				[2] = {
					[1] = {
						["Part"] = part,
						["CFrame"] = CFrame.new(part.Position) * CFrame.Angles(
